          "component": "Column",
          "children": [
            "title2",
            "desc2",
            "input_name",
            "input_legs",
            "picker_skills",
            "btn_generate",
            "div1",
            "result_title",
            "result_text"
          ]
        },
        {
          "id": "title2",
          "component": "Text",
          "text": "Fictional Dog Generator"
