          "id": "picker_skills",
          "component": "ChoicePicker",
          "label": "Skills & Abilities",
          "variant": "multipleSelection",
          "options": [
            {
              "label": "Super Jump",
              "value": "jump"
            },
            {
              "label": "Laser Eyes",
              "value": "laser"
            },
            {
              "label": "Telepathy",
              "value": "telepathy"
            },
            {
              "label": "Flight",
              "value": "flight"
            }
          ],
          "value": {
            "path": "/generator/skills"
          },
          "displayStyle": "chips"
        },
        {
          "id": "btn_generate_text",
          "component": "Text",
          "text": "Generate"
        },
        {
          "id": "btn_generate",
          "component": "Button",
          "child": "btn_generate_text",
          "variant": "primary",
          "action": {
            "event": {
              "name": "generate_dog",
              "context": {
                "name": {
                  "path": "/generator/name"
                },
                "legs": {
                  "path": "/generator/legs"
                },
                "skills": {
                  "path": "/generator/skills"
                }
              }
            }
          }
        },
        {
          "id": "div1",
          "component": "Divider",
          "axis": "horizontal"
        },
        {
          "id": "result_title",
          "component": "Text",
          "text": "Your Generated Fictional Dog Info:"
        },
        {
          "id": "result_text",
          "component": "Text",
          "text": {
            "path": "/generator/result"
          }
        }
      ],
      "dataModel": {
        "breeds": [
          {
            "url": "https://images.unsplash.com/photo-1543466835-00a7907e9de1",
            "name": "Golden Retriever"
          },
          {
            "url": "https://images.unsplash.com/photo-1517849845537-4d257902454a",
            "name": "Pug"
          },
          {
            "url": "https://images.unsplash.com/photo-1587300003388-59208cc962cb",
            "name": "Husky"
          }
        ],
        "generator": {
          "name": "",
          "legs": "4",
          "skills": [],
          "result": "Fill out the generator details and press 'Generate' to see your new fictional pet here!"
        }
      }
    }
  }
